WITH limits AS (SELECT date_trunc('hour',localtimestamp)+floor(extract(minute from localtimestamp)/30)*interval '30 minutes' AS b), ticks AS (SELECT generate_series(b-interval '48 hours',b,interval '30 minutes') ts FROM limits), attempts AS (SELECT u.testuser_user_id uid,u.testuser_creation_time s, LEAST(u.testuser_creation_time+t.test_duration_time*interval '1 minute',t.test_end_time,CASE WHEN u.testuser_status>=4 AND COALESCE(u.testuser_close_reason,'')<>'timeout' THEN COALESCE(u.testuser_last_activity,u.testuser_creation_time+t.test_duration_time*interval '1 minute') ELSE u.testuser_creation_time+t.test_duration_time*interval '1 minute' END) e FROM tce_tests_users u JOIN tce_tests t ON t.test_id=u.testuser_test_id CROSS JOIN limits WHERE u.testuser_status>0 AND NOT COALESCE(u.testuser_pregenerated,false) AND u.testuser_creation_time<=b AND u.testuser_creation_time+t.test_duration_time*interval '1 minute'>=b-interval '49 hours') SELECT extract(epoch FROM ts AT TIME ZONE 'Asia/Yekaterinburg')::bigint clock, count(distinct uid) FILTER (WHERE s>=ts-interval '30 minutes' AND s<ts) started_30m, count(distinct uid) FILTER (WHERE s<=ts AND e>ts) in_progress FROM ticks LEFT JOIN attempts ON s<=ts AND (e>ts OR s>=ts-interval '30 minutes') GROUP BY ts ORDER BY ts